from fastapi import FastAPI, File, UploadFile

app = FastAPI(title="Application Processor")


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


@app.post("/process")
async def process(file: UploadFile = File(...)) -> dict[str, object]:
    content = await file.read()
    return {
        "fileName": file.filename or "unknown",
        "contentType": file.content_type or "application/octet-stream",
        "sizeBytes": len(content),
        "status": "processed",
        "message": "Python processor received the application successfully.",
    }

var builder = WebApplication.CreateBuilder(args);
var processorUrl = builder.Configuration["PROCESSOR_URL"] ?? "http://localhost:8000";

builder.Services.AddHttpClient("processor", client => client.BaseAddress = new Uri(processorUrl));
builder.Services.AddCors(options => options.AddDefaultPolicy(policy =>
    policy.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));

var app = builder.Build();
app.UseCors();

app.MapGet("/api/health", () => Results.Ok(new { status = "ok" }));

app.MapPost("/api/applications", async (IFormFile file, IHttpClientFactory clients, CancellationToken cancellationToken) =>
{
    if (file.Length == 0)
    {
        return Results.BadRequest(new { message = "The uploaded file is empty." });
    }

    await using var stream = file.OpenReadStream();
    using var content = new MultipartFormDataContent();
    using var fileContent = new StreamContent(stream);
    fileContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(
        file.ContentType ?? "application/octet-stream");
    content.Add(fileContent, "file", file.FileName);

    var response = await clients.CreateClient("processor").PostAsync("/process", content, cancellationToken);
    var body = await response.Content.ReadAsStringAsync(cancellationToken);
    return Results.Content(body, "application/json", statusCode: (int)response.StatusCode);
})
.DisableAntiforgery();

app.Run();

