import { bootstrapApplication } from '@angular/platform-browser';
import { Component } from '@angular/core';
import { HttpClient, provideHttpClient } from '@angular/common/http';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
    <main>
      <h1>Application processor</h1>
      <p>Upload an application package to send it through the .NET API and Python processor.</p>
      <input type="file" (change)="selectFile($event)" />
      <button (click)="upload()" [disabled]="!file || loading">{{ loading ? 'Processing...' : 'Upload and process' }}</button>
      <p class="error" *ngIf="error">{{ error }}</p>
      <pre *ngIf="result">{{ result | json }}</pre>
    </main>
  `,
  styles: [`main { max-width: 720px; margin: 10vh auto; padding: 2rem; font: 16px system-ui; } input, button { margin: 1rem 1rem 1rem 0; padding: .7rem; } pre { background: #f3f4f6; padding: 1rem; } .error { color: #b91c1c; }`]
})
class AppComponent {
  file?: File;
  loading = false;
  result?: unknown;
  error = '';

  constructor(private readonly http: HttpClient) {}

  selectFile(event: Event) {
    const input = event.target as HTMLInputElement;
    this.file = input.files?.[0];
    this.error = '';
  }

  upload() {
    if (!this.file) return;
    const data = new FormData();
    data.append('file', this.file);
    this.loading = true;
    this.result = undefined;
    this.http.post('/api/applications', data).subscribe({
      next: value => { this.result = value; this.loading = false; },
      error: error => { this.error = error.error?.message ?? 'Upload failed.'; this.loading = false; }
    });
  }
}

bootstrapApplication(AppComponent, { providers: [provideHttpClient()] });

