using Npgsql;

var builder = WebApplication.CreateBuilder(args);
var processorUrl = builder.Configuration["PROCESSOR_URL"] ?? "http://localhost:8000";
var databaseUrl = builder.Configuration["DATABASE_URL"];

builder.Services.AddHttpClient("processor", client => client.BaseAddress = new Uri(processorUrl));
builder.Services.AddCors(options => options.AddDefaultPolicy(policy =>
    policy.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));

var app = builder.Build();
app.UseCors();

if (!string.IsNullOrWhiteSpace(databaseUrl))
{
    await using var database = new NpgsqlConnection(databaseUrl);
    await database.OpenAsync();
    await using var command = database.CreateCommand();
    command.CommandText = """
        CREATE TABLE IF NOT EXISTS application_runs (
            id BIGSERIAL PRIMARY KEY,
            file_name TEXT NOT NULL,
            result JSONB NOT NULL,
            processed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
        """;
    await command.ExecuteNonQueryAsync();
}

app.MapGet("/api/health", () => Results.Ok(new { status = "ok" }));

app.MapPost("/api/applications", async (IFormFile file, IHttpClientFactory clients, CancellationToken cancellationToken) =>
{
    if (file.Length == 0)
    {
        return Results.BadRequest(new { message = "The uploaded file is empty." });
    }

    await using var stream = file.OpenReadStream();
    using var content = new MultipartFormDataContent();
    using var fileContent = new StreamContent(stream);
    fileContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(
        file.ContentType ?? "application/octet-stream");
    content.Add(fileContent, "file", file.FileName);

    var response = await clients.CreateClient("processor").PostAsync("/process", content, cancellationToken);
    var body = await response.Content.ReadAsStringAsync(cancellationToken);

    if (response.IsSuccessStatusCode && !string.IsNullOrWhiteSpace(databaseUrl))
    {
        await using var database = new NpgsqlConnection(databaseUrl);
        await database.OpenAsync(cancellationToken);
        await using var command = database.CreateCommand();
        command.CommandText = "INSERT INTO application_runs (file_name, result) VALUES ($1, $2::jsonb)";
        command.Parameters.AddWithValue(file.FileName);
        command.Parameters.AddWithValue(body);
        await command.ExecuteNonQueryAsync(cancellationToken);
    }

    return Results.Content(body, "application/json", statusCode: (int)response.StatusCode);
})
.DisableAntiforgery();

app.Run();

import os

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, HttpUrl
from selenium import webdriver
from selenium.webdriver.chrome.options import Options

app = FastAPI(title="Browser Robot")


class RobotRequest(BaseModel):
    url: HttpUrl


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


@app.post("/run")
def run_robot(request: RobotRequest) -> dict[str, str]:
    options = Options()
    options.add_argument("--headless")
    options.add_argument("--no-sandbox")
    options.add_argument("--disable-dev-shm-usage")
    driver = None
    try:
        driver = webdriver.Remote(
            command_executor=os.getenv("SELENIUM_URL", "http://localhost:4444"),
            options=options,
        )
        driver.get(str(request.url))
        return {"url": driver.current_url, "title": driver.title, "status": "completed"}
    except Exception as error:
        raise HTTPException(status_code=502, detail=str(error)) from error
    finally:
        if driver:
            driver.quit()

pipeline {
    agent any

    stages {
        stage('Validate Python') {
            steps { bat 'python -m py_compile services\\processor\\app.py services\\robot\\app.py' }
        }
        stage('Build Angular') {
            steps { bat 'cd apps\\web && npm ci && npm run build' }
        }
        stage('Build Containers') {
            steps { bat 'docker compose build' }
        }
    }
    post {
        always { junit allowEmptyResults: true, testResults: '**/test-results/*.xml' }
    }
}

