import { bootstrapApplication } from '@angular/platform-browser';
import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import JSZip from 'jszip';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
    <main>
      <h1>Application upload</h1>
      <p>Select the complete project ZIP to inspect its files locally in the browser.</p>
      <input type="file" accept=".zip,application/zip" (change)="selectFile($event)" />
      <button (click)="inspect()" [disabled]="!file || loading">{{ loading ? 'Inspecting...' : 'Inspect project' }}</button>
      <p class="error" *ngIf="error">{{ error }}</p>
      <section *ngIf="result" class="result">
        <h2>{{ result.fileName }}</h2>
        <p>{{ result.fileCount }} files found, {{ result.sizeBytes | number }} bytes.</p>
        <p class="status" [class.invalid]="!result.isProject">{{ result.isProject ? 'Project structure detected' : 'Project markers are incomplete' }}</p>
        <ul><li *ngFor="let fileName of result.files">{{ fileName }}</li></ul>
      </section>
    </main>
  `,
  styles: [`main { max-width: 720px; margin: 10vh auto; padding: 2rem; font: 16px system-ui; } input, button { margin: 1rem 1rem 1rem 0; padding: .7rem; } pre { background: #f3f4f6; padding: 1rem; } .error { color: #b91c1c; }`]
})
class AppComponent {
  file?: File;
  loading = false;
  result?: InspectionResult;
  error = '';

  selectFile(event: Event) {
    const input = event.target as HTMLInputElement;
    this.file = input.files?.[0];
    this.error = '';
  }

  async inspect() {
    if (!this.file) return;
    this.loading = true;
    this.result = undefined;
    this.error = '';
    try {
      if (!this.file.name.toLowerCase().endsWith('.zip')) {
        throw new Error('Choose a ZIP containing the complete project.');
      }
      const archive = await JSZip.loadAsync(this.file);
      const files = Object.keys(archive.files).filter(fileName => !archive.files[fileName].dir).sort();
      const markers = ['apps/web/package.json', 'docker-compose.yml', 'Jenkinsfile', 'services/robot/app.py'];
      const normalizedFiles = files.map(fileName => fileName.replace(/^[^/]+\//, ''));
      this.result = {
        fileName: this.file.name,
        sizeBytes: this.file.size,
        fileCount: files.length,
        files,
        isProject: markers.every(marker => normalizedFiles.includes(marker))
      };
    } catch (error) {
      this.error = error instanceof Error ? error.message : 'The ZIP could not be inspected.';
    } finally {
      this.loading = false;
    }
  }
}

interface InspectionResult {
  fileName: string;
  sizeBytes: number;
  fileCount: number;
  files: string[];
  isProject: boolean;
}

bootstrapApplication(AppComponent);

