import { bootstrapApplication } from '@angular/platform-browser';
import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import JSZip from 'jszip';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
    <main>
      <h1>Application upload</h1>
      <p>Select a project ZIP to run a zero-touch browser regression.</p>
      <input type="file" accept=".zip,application/zip" (change)="selectFile($event)" />
      <button (click)="inspect()" [disabled]="!file || loading">{{ loading ? 'Running regression...' : 'Run zero-touch regression' }}</button>
      <p class="error" *ngIf="error">{{ error }}</p>
      <section *ngIf="result" class="result">
        <h2>{{ result.fileName }}</h2>
        <p class="status" [class.invalid]="result.status !== 'passed'">{{ result.status === 'passed' ? 'Regression passed' : 'Regression failed' }}</p>
        <p>Engine: {{ result.engine }}</p>
        <p *ngIf="result.title">Page title: {{ result.title }}</p>
        <p *ngIf="result.entryPoint">Entry point: {{ result.entryPoint }}</p>
      </section>
    </main>
  `,
  styles: [`main { max-width: 720px; margin: 10vh auto; padding: 2rem; font: 16px system-ui; } input, button { margin: 1rem 1rem 1rem 0; padding: .7rem; } .result { background: #f3f4f6; padding: 1rem; } .result ul { max-height: 18rem; overflow: auto; } .error, .invalid { color: #b91c1c; } .status { color: #166534; font-weight: 600; }`]
})
class AppComponent {
  file?: File;
  loading = false;
  result?: InspectionResult;
  error = '';

  selectFile(event: Event) {
    const input = event.target as HTMLInputElement;
    this.file = input.files?.[0];
    this.error = '';
  }

  async inspect() {
    if (!this.file) return;
    this.loading = true;
    this.result = undefined;
    this.error = '';
    try {
      if (!this.file.name.toLowerCase().endsWith('.zip')) {
        throw new Error('Choose a ZIP containing the complete project.');
      }
      const archive = await JSZip.loadAsync(this.file);
      const files = Object.keys(archive.files).filter(fileName => !archive.files[fileName].dir).sort();
      if (!files.some(fileName => fileName.endsWith('index.html'))) {
        throw new Error('The package must contain an index.html entry point.');
      }
      const response = await fetch('/regress', {
        method: 'POST',
        body: (() => { const data = new FormData(); data.append('file', this.file!); return data; })()
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.detail ?? 'Regression failed.');
      this.result = body;
    } catch (error) {
      this.error = error instanceof Error ? error.message : 'The ZIP could not be inspected.';
    } finally {
      this.loading = false;
    }
  }
}

interface InspectionResult {
  fileName: string;
  status: string;
  engine: string;
  fileCount: number;
  entryPoint?: string;
  title?: string;
}

bootstrapApplication(AppComponent);

