@import "bootstrap/dist/css/bootstrap.min.css";
@import "tailwindcss";

:root {
	font-family: "Trebuchet MS", "Segoe UI", sans-serif;
	color: #172326;
	background: #f4f1eb;
	font-synthesis: none;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; background: #f4f1eb; }
button, input { font: inherit; }
button { cursor: pointer; }

.shell { max-width: 1180px; min-height: 100vh; margin: 0 auto; padding: 0 42px 38px; position: relative; overflow: hidden; }
.shell::before { content: ""; position: absolute; z-index: -1; width: 540px; height: 540px; right: -230px; top: 110px; border: 1px solid #d5cec2; border-radius: 50%; box-shadow: 0 0 0 54px #f4f1eb, 0 0 0 55px #ddd6ca, 0 0 0 110px #f4f1eb, 0 0 0 111px #e6dfd5; }
.topbar { display: flex; align-items: center; justify-content: space-between; padding: 25px 0; border-bottom: 1px solid #dcd5c9; }
.brand { display: flex; align-items: center; gap: 10px; color: #172326; text-decoration: none; font-size: 19px; font-weight: 700; letter-spacing: .02em; }
.brand-mark { display: grid; place-items: center; width: 29px; height: 29px; color: #f4f1eb; background: #e85d3f; border-radius: 8px 8px 8px 2px; font-family: Georgia, serif; font-size: 19px; }
.brand-dot { color: #e85d3f; }
.topbar-meta { color: #7d827c; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; }
.theme-button { width: 27px; height: 27px; margin-left: 12px; padding: 0; color: #172326; background: transparent; border: 1px solid #cfc7ba; border-radius: 50%; font-size: 14px; line-height: 1; transition: background .2s, color .2s, border-color .2s; }.theme-button:hover { color: #fffdf9; background: #e85d3f; border-color: #e85d3f; }
.live-dot { display: inline-block; width: 7px; height: 7px; margin-right: 7px; background: #3c9b76; border-radius: 50%; box-shadow: 0 0 0 4px #dcebe2; }
.divider { display: inline-block; height: 13px; margin: 0 12px -2px; border-left: 1px solid #cac2b5; }
.intro { max-width: 690px; padding: 91px 0 54px; }
.eyebrow, .section-kicker { color: #e85d3f; font-size: 11px; font-weight: 700; letter-spacing: .18em; }
.eyebrow { display: flex; align-items: center; gap: 10px; }
.eyebrow-line { display: inline-block; width: 31px; border-top: 2px solid #e85d3f; }
h1, h2, p { margin-top: 0; }
h1 { margin: 19px 0 17px; color: #172326; font-family: Georgia, serif; font-size: clamp(54px, 8vw, 94px); font-weight: 400; letter-spacing: -.055em; line-height: .89; }
h1 em { color: #e85d3f; font-style: italic; }
.lede { max-width: 470px; color: #68716d; font-size: 16px; line-height: 1.65; }
.workspace, .result-panel { background: #fffdf9; border: 1px solid #ddd6cc; box-shadow: 0 20px 50px #44362b0d; }
.workspace { padding: 29px 34px 25px; }
.workspace-head, .result-heading, .action-row, .result-main { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.workspace-head h2 { margin: 8px 0 0; font-family: Georgia, serif; font-size: 27px; font-weight: 400; }
.format-pill { color: #3c9b76; background: #e7f2eb; padding: 8px 11px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.format-pill span { color: #7a9d8b; margin-left: 7px; font-weight: 400; }
.dropzone { display: flex; min-height: 186px; margin: 28px 0 19px; flex-direction: column; align-items: center; justify-content: center; border: 1px dashed #c9c0b3; background: #faf8f3; transition: border-color .2s, background .2s; cursor: pointer; }
.dropzone:hover, .dropzone.has-file { border-color: #e85d3f; background: #fff6f1; }
.dropzone input { display: none; }
.upload-icon { position: relative; display: block; width: 37px; height: 37px; margin-bottom: 13px; border: 1px solid #e85d3f; border-radius: 50%; }
.upload-icon::before { content: ""; position: absolute; width: 1px; height: 14px; left: 17px; top: 8px; background: #e85d3f; }
.upload-icon::after { content: ""; position: absolute; width: 8px; height: 8px; left: 13px; top: 8px; border-left: 1px solid #e85d3f; border-top: 1px solid #e85d3f; transform: rotate(45deg); }
.upload-icon span { position: absolute; width: 13px; height: 1px; left: 11px; bottom: 9px; background: #e85d3f; }
.drop-title { color: #273336; font-family: Georgia, serif; font-size: 20px; }
.drop-note { margin-top: 7px; color: #949991; font-size: 12px; }
.helper-text { color: #858b85; font-size: 12px; }
